<?php require 'includes/layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$stmt=db()->prepare('SELECT * FROM users WHERE email=?');$stmt->execute([trim($_POST['email']??'')]);$found=$stmt->fetch();if($found&&password_verify($_POST['password']??'',$found['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$found['id'],'username'=>$found['username'],'role'=>$found['role']];redirect('profile.php');}$error='Incorrect email or password.';}top('Log In'); ?><div class="panel"><p>Welcome back! Log in to track your scores.</p><?php if(isset($error)):?><p class="error"><?=e($error)?></p><?php endif;?><form class="form" method="post"><?php csrf_field();?><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn">Log in</button></form><p><a href="forgot-password.php">Forgot password?</a> · <a href="register.php">Create account</a></p></div><?php bottom(); ?>